@Test
    void testNormalizePreciseLowerBound_oe() {
        final double x = Math.PI / 3;
        final double above = Math.nextUp(x);
        final double below = Math.nextDown(x);

        final DoubleUnaryOperator normalizer = Angle.Rad.normalizer(x);

        Assertions.assertEquals(x, normalizer.applyAsDouble(x));
        Assertions.assertEquals(above, normalizer.applyAsDouble(above));

        // "below" is so close to "x" that below + Math.PI = x + Math.PI
        // In this case, we can't return below + Math.PI because that is exactly equal to the
        // upper bound of the range. Instead, we must return the lower bound of x.
        Assertions.assertEquals(x, normalizer.applyAsDouble(below));
    }

@Test
    void testCosAngle2D_oe() {
        double expected;

        final double[] v1 = {1, 0};
        expected = 1;
        Assertions.assertEquals(expected, CosAngle.value(v1, v1));

        final double[] v2 = {0, 1};
        expected = 0;
        Assertions.assertEquals(expected, CosAngle.value(v1, v2));

        final double[] v3 = {7, 7};
        expected = Math.sqrt(2) / 2;
        Assertions.assertEquals(expected, CosAngle.value(v1, v3), 1e-15);
        Assertions.assertEquals(expected, CosAngle.value(v3, v2), 1e-15);

        final double[] v4 = {-5, 0};
        expected = -1;
        Assertions.assertEquals(expected, CosAngle.value(v1, v4));

        final double[] v5 = {-100, 100};
        expected = 0;
        Assertions.assertEquals(expected, CosAngle.value(v3, v5));
    }

