        final double[] yE = {9, 1, 4, 16, 25};
        final double[] zE = {27, 1, 8, 64, -125};

        Assertions.assertArrayEquals(xE, x);
        Assertions.assertArrayEquals(yE, y);
        Assertions.assertArrayEquals(zE, z);
    }

